begin;
do $$
declare uid uuid; cid uuid; cid2 uuid; sid uuid; linked uuid=gen_random_uuid(); req uuid=gen_random_uuid(); p jsonb; rowdata jsonb; result jsonb; caught boolean;
begin
 select user_id into uid from public.payroll_members where role='admin' limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 cid=(public.payroll_api('company_create','{"name":"QA staff import rollback"}')->>'id')::uuid;
 cid2=(public.payroll_api('company_create','{"name":"QA isolated company rollback"}')->>'id')::uuid;
 rowdata=jsonb_build_object('department','QA','designation','Tester','code','IMP01','name','Import Sample','email','import-sample@example.invalid','joining_date','2026-10-01','basic',20000,'da',1000,'hra',2000,'other',0,'shift_name','Night','shift_start','22:00','shift_end','06:00','break_minutes',30,'late_grace',10,'early_grace',5);
 p=jsonb_build_object('company_id',cid,'request_id',req,'rows',jsonb_build_array(rowdata));
 result=public.payroll_api('staff_import',p);perform public.payroll_api('staff_import',p);
 if result->>'inserted'<>'1' or (select count(*) from public.payroll_staff where company_id=cid)<>1 then raise exception 'Import/replay failed';end if;
 select id into sid from public.payroll_staff where company_id=cid and code='IMP01';
 if not exists(select 1 from public.payroll_staff where id=sid and shift_start='22:00' and break_minutes=30) then raise exception 'Shift not saved';end if;
 caught=false;begin perform public.payroll_api('staff_import',jsonb_build_object('company_id',cid,'rows',jsonb_build_array(rowdata||'{"code":"NEW01","email":"new-row@example.invalid"}',rowdata)));exception when others then caught=true;end;
 if not caught or exists(select 1 from public.payroll_staff where company_id=cid and code='NEW01') then raise exception 'Partial import or duplicate overwrite';end if;
 caught=false;begin perform public.payroll_api('staff_import',jsonb_build_object('company_id',cid,'rows',jsonb_build_array(rowdata||'{"code":"imp01","email":"case@example.invalid"}')));exception when others then caught=true;end;
 if not caught then raise exception 'Case-insensitive duplicate bypass';end if;
 caught=false;begin perform public.payroll_api('staff_save',rowdata||jsonb_build_object('company_id',cid,'staff_id',sid,'shift_end','22:00'));exception when others then caught=true;end;
 if not caught then raise exception 'Zero-length shift saved';end if;
 perform public.payroll_api('attendance_save',jsonb_build_object('company_id',cid,'staff_id',sid,'from_date','2026-10-02','to_date','2026-10-02','status','present','in_time','22:20','out_time','05:45','out_next_day',true,'calculate_shift',true));
 if not exists(select 1 from public.payroll_attendance where staff_id=sid and late_minutes=10 and early_minutes=10 and shift_snapshot->>'name'='Night') then raise exception 'Night shift calculation failed';end if;
 perform public.payroll_api('staff_save',rowdata||jsonb_build_object('company_id',cid,'staff_id',sid,'shift_start','21:00'));
 if not exists(select 1 from public.payroll_attendance where staff_id=sid and late_minutes=10 and shift_snapshot->>'start'='22:00:00') then raise exception 'Shift history changed retroactively';end if;
 caught=false;begin perform public.payroll_api('staff_delete',jsonb_build_object('company_id',cid,'staff_id',sid,'confirm_code','IMP01'));exception when others then caught=true;end;
 if not caught or not exists(select 1 from public.payroll_staff where id=sid) then raise exception 'Historical record deleted';end if;
 caught=false;begin perform public.payroll_api('staff_delete',jsonb_build_object('company_id',cid2,'staff_id',sid,'confirm_code','IMP01'));exception when others then caught=true;end;
 if not caught then raise exception 'Cross-company deletion';end if;
 sid=(public.payroll_api('staff_save',rowdata||jsonb_build_object('company_id',cid,'code','REMOVE','email','remove@example.invalid'))->>'id')::uuid;
 caught=false;begin perform public.payroll_api('staff_delete',jsonb_build_object('company_id',cid,'staff_id',sid,'confirm_code','WRONG'));exception when others then caught=true;end;
 if not caught then raise exception 'Unconfirmed deletion';end if;
 perform public.payroll_api('staff_delete',jsonb_build_object('company_id',cid,'staff_id',sid,'confirm_code','REMOVE'));
 if exists(select 1 from public.payroll_staff where id=sid) then raise exception 'Unused staff not deleted';end if;
 insert into auth.users(id,email,email_confirmed_at) values(linked,'qa-staff-import-role@example.invalid',now());
 insert into public.payroll_members values(cid,linked,'accountant');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',linked,'role','authenticated')::text,true);
 caught=false;begin perform public.payroll_api('staff_import',p-'request_id');exception when others then caught=true;end;
 if not caught then raise exception 'Accountant import permitted';end if;
 caught=false;begin perform public.payroll_api('staff_delete',jsonb_build_object('company_id',cid,'staff_id',(select id from public.payroll_staff where company_id=cid limit 1),'confirm_code','IMP01'));exception when others then caught=true;end;
 if not caught then raise exception 'Accountant deletion permitted';end if;
end$$;
rollback;
select 'PASS: atomic import, replay, duplicate protection, shift validation, overnight calculations, historical snapshot, deletion guards, tenant and role denial' as result;
